// src/lib/mcp/tools/get-journal-entry.ts
import { defineTool as defineTool5 } from "npm:@lovable.dev/mcp-js@0.24.0";
import { z as z2 } from "npm:zod@^3.25.76";
var SITE_ORIGIN3 = "https://ivandemurard.com";
function renderBlock(block) {
  switch (block.kind) {
    case "p":
      return block.text;
    case "h2":
      return `## ${block.text}`;
    case "h3":
      return `### ${block.text}`;
    case "quote":
      return `> ${block.text}`;
    case "list":
      return block.items.map((i) => `- ${i}`).join("\n");
    case "code":
      return `\`\`\`${block.lang ?? ""}
${block.text}
\`\`\``;
    case "table":
      return [
        `| ${block.head.join(" | ")} |`,
        `| ${block.head.map(() => "---").join(" | ")} |`,
        ...block.rows.map((r) => `| ${r.join(" | ")} |`)
      ].join("\n");
    case "defs":
      return block.items.map((i) => `**${i.term}**: ${i.def}${i.note ? `
*${i.note}*` : ""}`).join("\n");
    case "pyramid":
      return block.layers.map((l) => `${l.level}: ${l.name}${l.note ? ` (${l.note})` : ""}${l.base ? " [foundation]" : ""}`).join("\n");
    case "deployed":
      return block.items.map((i) => `Deployed: ${i.project} (${SITE_ORIGIN3}${i.to}) ${i.text}`).join("\n");
    case "lines":
      return block.items.map((i) => `Q: ${i.q}
A: ${i.a}`).join("\n\n");
    case "key":
      return `**${block.sigil}** ${block.oneLine}${block.concrete ? ` Concrete case: ${block.concrete}` : ""}`;
    case "anchors":
      return block.items.map((i) => `**${i.project}** (${SITE_ORIGIN3}${i.to}): ${i.what} Users: ${i.who} Feedback: ${i.feedback}`).join("\n");
    case "timeline":
      return block.steps.map((i) => `${i.value}: ${i.label}${i.note ? ` (${i.note})` : ""}`).join("\n");
    case "cards":
      return block.items.map((i) => `**${i.title}**: ${i.body}`).join("\n\n");
    case "matrix":
      return [block.columns.join(" | "), ...block.rows.map((r) => `${r.arm} (${r.when}): ${r.cells.map((c) => `${c.state}: ${c.instance}${c.cost ? ` (${c.cost})` : ""}`).join(" | ")}`)].join("\n");
    case "vocab":
      return block.items.map((i) => i.label).join(", ");
    case "askRose":
      return [block.label, block.note, ...block.prompts].filter(Boolean).join("\n");
    case "stepper":
      return [
        block.label ? `**${block.label}**` : "",
        `Technician: ${block.question} (${block.rule})`,
        `Model answer, verbatim: "${block.answer}"`,
        ...block.steps.map(
          (st, i) => `Step ${i + 1}, ${st.tab}: ${st.verdict}. ${st.checks.map((c) => `${c.grader}: ${c.result}`).join("; ")}.${st.answer ? ` What ships: "${st.answer}"` : ""} ${st.reading}`
        ),
        block.note ?? ""
      ].filter(Boolean).join("\n");
    case "fold":
      return [`**${block.summary}**`, ...block.blocks.map(renderBlock)].filter(Boolean).join("\n\n");
    case "recoLine":
      return [`**Figure.** ${block.caption}`, recoLineMarkdown(block.layer), block.link ? `${block.link.text}: ${SITE_ORIGIN3}${block.link.to}` : ""].filter(Boolean).join("\n\n");
    case "console":
    case "mcp":
      return "";
    case "arms":
      return [block.label, "Arm A: offline before the merge. Arm B: runtime in production. Arm C: outcome after the fact.", block.link ? `${block.link.text}: ${SITE_ORIGIN3}${block.link.to}` : ""].filter(Boolean).join("\n");
  }
}
function renderEntryMarkdown(entry) {
  const bodyText2 = entry.body.map(renderBlock).filter(Boolean).join("\n\n");
  const url = `${SITE_ORIGIN3}/journal/${entry.slug}`;
  return [
    `# ${entry.title}`,
    entry.subtitle ?? "",
    `${entry.category} \xB7 ${entry.date}${entry.readingMinutes ? ` \xB7 ${entry.readingMinutes} min read` : ""}`,
    entry.tldr ? `**TL;DR** - ${entry.tldr}` : "",
    entry.glance ? `**Read this if** ${entry.glance.audience} **What it gives you**: ${entry.glance.promise} **Tested on**: ${entry.glance.proof}` : "",
    entry.takeaways?.length ? `What you will decide differently:
${entry.takeaways.map((t) => `- ${t}`).join("\n")}` : "",
    entry.takeawayPunch ?? "",
    entry.diagnostic ? `**${entry.diagnostic.label}.** ${entry.diagnostic.intro}
${entry.diagnostic.questions.map((q, i) => `${i + 1}. (Arm ${q.arm}) ${q.ask} If not: ${q.gap} See ${SITE_ORIGIN3}/journal/${entry.slug}#${q.to}`).join("\n")}
${entry.diagnostic.caveat}` : "",
    entry.excerpt,
    bodyText2,
    entry.updates?.length ? `## Updates

This piece is revised when something it claims stops being true. Each revision says what changed and why.

${entry.updates.map((u) => `${u.date} \xB7 ${u.summary} ${u.reason}`).join("\n")}` : "",
    entry.license ? `Licence: ${entry.license.label} (${entry.license.url}). ${entry.license.note ?? ""}` : "",
    `Source: ${url}`
  ].filter(Boolean).join("\n\n");
  ;
}
var get_journal_entry_default = defineTool5({
  name: "get_journal_entry",
  title: "Get Field Note",
  description: "Fetch one Field Notes entry in full by slug: title, subtitle, date, category and the complete body rendered as readable Markdown. Use list_journal_entries to discover valid slugs.",
  inputSchema: {
    slug: z2.string().describe("Field Note slug, as returned by list_journal_entries.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ slug }) => {
    const entry = JOURNAL_ENTRIES.find((e) => e.slug === slug);
    if (!entry) {
      const available = JOURNAL_ENTRIES.map((e) => e.slug).join(", ");
      return {
        content: [
          {
            type: "text",
            text: `Unknown Field Note slug "${slug}". Available slugs: ${available || "none"}.`
          }
        ],
        isError: true
      };
    }
    const url = `${SITE_ORIGIN3}/journal/${entry.slug}`;
    const text = renderEntryMarkdown(entry);
    return {
      content: [{ type: "text", text }],
      structuredContent: {
        slug: entry.slug,
        title: entry.title,
        subtitle: entry.subtitle ?? null,
        date: entry.date,
        category: entry.category,
        excerpt: entry.excerpt,
        reading_minutes: entry.readingMinutes ?? null,
        related: entry.related ?? [],
        url,
        tldr: entry.tldr ?? null,
        glance: entry.glance ?? null,
        takeaways: entry.takeaways ?? [],
        takeaway_punch: entry.takeawayPunch ?? null,
        diagnostic: entry.diagnostic ?? null,
        updates: entry.updates ?? [],
        markdown_url: entry.mirror ? `${SITE_ORIGIN3}${entry.mirror}` : null,
        body: entry.body,
        body_text: bodyText
      }
    };
  }
});

